sys_script.script:
(function executeRule(current, previous) {
    // Function to generate serial number 
    function AutoNumber() {
        var suf = "ASS";
        var otp = Math.floor(100000 + Math.random() * 900000);
        return suf + otp;
    } // Create new Asset
    var newAsset = new GlideRecord("alm_hardware");
    newAsset.initialize();
    newAsset.serial_number = AutoNumber();
    var categoryGR = new GlideRecord("cmdb_model_category");
    categoryGR.addQuery("name", "Hardware");
    categoryGR.query();
    if (categoryGR.next()) {
        newAsset.model_category = categoryGR.sys_id;
    }
	if (current.cat_item && current.cat_item.name) {
        var itemName = current.cat_item.name.trim();
        gs.info("Catalog Item: " + itemName);

        var modelGR = new GlideRecord("cmdb_hardware_product_model");
        modelGR.addQuery('display_name',current.cat_item.getDisplayValue());
        modelGR.query();
        while(modelGR.next())
		{
			gs.info("Catalog Item: " + itemName);
            newAsset.model = modelGR.sys_id;
		}
	}
    var grr = new GlideRecord("csm_consumer");
    grr.addQuery("name", current.requested_for.name);
    grr.query();
    if (grr.next()) {
        newAsset.consumer = grr.sys_id;
        gs.info("Consumer assigned: " + grr.name);
    } 
	//newAsset.install_date = gs.nowDateTime();
    newAsset.status = "in_use";
    var assetId = newAsset.insert();
    gs.info("New Asset created from RITM " + current.number + ": " + assetId);
})(current, previous);
